//! Checks tickets and signed manifest records against
//! `docs/test-vectors/ticket-v1.json`, generated by an independent Python
//! implementation (`generate_ticket_v1.py`).

use std::net::{IpAddr, SocketAddr};

use ourstick_core::record::RECORD_FORMAT_VERSION;
use ourstick_core::ticket::TICKET_FORMAT_VERSION;
use ourstick_core::{
    AddressHint, ManifestHint, NodeId, RecordError, SignedManifestRecord, StickKey,
    StickSigningKey, Ticket,
};
use serde::Deserialize;

const VECTORS: &str = include_str!("../../../docs/test-vectors/ticket-v1.json");

#[derive(Deserialize)]
struct Document {
    ticket_format_version: u8,
    record_format_version: u8,
    tickets: Vec<TicketVector>,
    records: Vec<RecordVector>,
}

#[derive(Deserialize)]
struct TicketVector {
    name: String,
    signing_seed: String,
    stick_id: String,
    node_id: String,
    manifest_seq: u64,
    manifest_hash: String,
    address_hints: Vec<HintVector>,
    stick_key: String,
    link: String,
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
enum HintVector {
    Ipv4 { ip: String, port: u16 },
    Ipv6 { ip: String, port: u16 },
    Relay { url: String },
}

#[derive(Deserialize)]
struct RecordVector {
    name: String,
    signing_seed: String,
    stick_id: String,
    seq: u64,
    manifest_hash: String,
    record: String,
    /// Outcome against the tickets' manifest hint, with no seq seen before.
    against_ticket: String,
}

fn document() -> Document {
    serde_json::from_str(VECTORS).expect("ticket-v1.json is valid")
}

fn hex(text: &str) -> Vec<u8> {
    data_encoding::HEXLOWER.decode(text.as_bytes()).unwrap()
}

fn hex32(text: &str) -> [u8; 32] {
    hex(text).try_into().unwrap()
}

impl HintVector {
    fn to_hint(&self) -> AddressHint {
        match self {
            Self::Ipv4 { ip, port } | Self::Ipv6 { ip, port } => {
                SocketAddr::new(ip.parse::<IpAddr>().unwrap(), *port).into()
            }
            Self::Relay { url } => AddressHint::Relay { url: url.clone() },
        }
    }
}

impl TicketVector {
    fn ticket(&self) -> Ticket {
        let signing_key = StickSigningKey::from_bytes(&hex32(&self.signing_seed));
        assert_eq!(
            signing_key.stick_id().to_bytes(),
            hex32(&self.stick_id),
            "{}",
            self.name
        );
        Ticket {
            stick_id: signing_key.stick_id(),
            node_id: NodeId(hex32(&self.node_id)),
            manifest_hint: ManifestHint {
                seq: self.manifest_seq,
                hash: hex32(&self.manifest_hash),
            },
            address_hints: self.address_hints.iter().map(HintVector::to_hint).collect(),
            stick_key: StickKey::from_bytes(hex32(&self.stick_key)),
        }
    }
}

#[test]
fn format_versions_match_implementation() {
    let document = document();
    assert_eq!(document.ticket_format_version, TICKET_FORMAT_VERSION);
    assert_eq!(document.record_format_version, RECORD_FORMAT_VERSION);
    assert_eq!(document.tickets.len(), 2);
    assert_eq!(document.records.len(), 4);
}

#[test]
fn tickets_encode_to_vector_links() {
    for vector in document().tickets {
        assert_eq!(
            vector.ticket().to_link().unwrap(),
            vector.link,
            "{}",
            vector.name
        );
    }
}

#[test]
fn vector_links_decode_to_tickets() {
    for vector in document().tickets {
        let parsed: Ticket = vector.link.parse().unwrap();
        assert_eq!(parsed, vector.ticket(), "{}", vector.name);
    }
}

#[test]
fn records_sign_to_vector_bytes() {
    // Ed25519 signatures are deterministic, so the whole record must match.
    for vector in document().records {
        let signing_key = StickSigningKey::from_bytes(&hex32(&vector.signing_seed));
        assert_eq!(signing_key.stick_id().to_bytes(), hex32(&vector.stick_id));
        let signed = signing_key.sign_record(vector.seq, hex32(&vector.manifest_hash));
        assert_eq!(
            signed.to_bytes().to_vec(),
            hex(&vector.record),
            "{}",
            vector.name
        );
    }
}

#[test]
fn vector_records_verify_against_ticket_hint() {
    let document = document();
    let ticket_hint = document.tickets[0].ticket().manifest_hint;
    for vector in document.records {
        let name = &vector.name;
        let signing_key = StickSigningKey::from_bytes(&hex32(&vector.signing_seed));
        let parsed = SignedManifestRecord::from_bytes(&hex(&vector.record)).unwrap();
        let result = parsed.verify(&signing_key.stick_id(), &ticket_hint, None);
        match vector.against_ticket.as_str() {
            "accept" => {
                let record = result.unwrap();
                assert_eq!(record.seq, vector.seq, "{name}");
                assert_eq!(record.manifest_hash, hex32(&vector.manifest_hash), "{name}");
            }
            "older_than_ticket" => assert!(
                matches!(result, Err(RecordError::OlderThanTicket { .. })),
                "{name}: {result:?}"
            ),
            "conflicts_with_ticket" => assert!(
                matches!(result, Err(RecordError::ConflictsWithTicket { .. })),
                "{name}: {result:?}"
            ),
            other => panic!("{name}: unknown outcome {other}"),
        }
    }
}
